style.css:
@-moz-document domain("youtube.com") {
/* ─── TOKENS ──────────────────────────────────────────────── */
  :root {
    --glass-bg:            rgba(255, 255, 255, 0.10);
    --glass-bg-hover:      rgba(255, 255, 255, 0.18);
    --glass-bg-active:     rgba(255, 255, 255, 0.24);
    --glass-border:        rgba(255, 255, 255, 0.22);
    --glass-border-strong: rgba(255, 255, 255, 0.40);
    --glass-blur:          blur(24px) saturate(180%);
    --glass-blur-light:    blur(14px) saturate(160%);
    --glass-shadow:        0 4px 24px rgba(0,0,0,0.18), 0 1.5px 6px rgba(0,0,0,0.10);
    --glass-shadow-hover:  0 8px 40px rgba(0,0,0,0.22), 0 2px 10px rgba(0,0,0,0.12);
    --glass-radius-sm:     12px;
    --glass-radius-md:     20px;
    --glass-radius-lg:     28px;
    --glass-radius-pill:   999px;
    --glass-tint:          rgba(120, 180, 255, 0.06); /* subtle cool tint like visionOS */
  }

  /* ─── MASTHEAD / TOP NAV ──────────────────────────────────── */
  #masthead-container,
  ytd-masthead {
    background: rgba(10, 10, 20, 0.55) !important;
    backdrop-filter: var(--glass-blur) !important;
    -webkit-backdrop-filter: var(--glass-blur) !important;
    border-bottom: 1px solid var(--glass-border) !important;
    box-shadow: 0 2px 32px rgba(0,0,0,0.20) !important;
  }

  /* ─── SEARCH BAR ──────────────────────────────────────────── */
  ytd-searchbox,
  #search-form,
  #search {
    background: var(--glass-bg) !important;
    backdrop-filter: var(--glass-blur-light) !important;
    -webkit-backdrop-filter: var(--glass-blur-light) !important;
    border: 1px solid var(--glass-border) !important;
    border-radius: var(--glass-radius-pill) !important;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.15), var(--glass-shadow) !important;
    overflow: hidden !important;
    transition: border-color 0.2s, box-shadow 0.2s !important;
  }

  ytd-searchbox:focus-within,
  #search-form:focus-within {
    border-color: var(--glass-border-strong) !important;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.20), var(--glass-shadow-hover), 0 0 0 3px rgba(120,180,255,0.15) !important;
  }

  #search-input input,
  ytd-searchbox input {
    background: transparent !important;
    color: inherit !important;
  }

  /* Search button */
  #search-icon-legacy,
  #search-icon-legacy button,
  ytd-searchbox #search-icon-legacy {
    background: var(--glass-bg-active) !important;
    backdrop-filter: var(--glass-blur-light) !important;
    -webkit-backdrop-filter: var(--glass-blur-light) !important;
    border-left: 1px solid var(--glass-border) !important;
    border-radius: 0 var(--glass-radius-pill) var(--glass-radius-pill) 0 !important;
  }

  /* ─── GUIDE / LEFT SIDEBAR ────────────────────────────────── */
  #guide-content,
  ytd-guide-renderer,
  #contentContainer.ytd-app[guide-persistent-and-visible] ytd-page-manager {
    background: transparent !important;
  }

  ytd-guide-entry-renderer,
  ytd-mini-guide-entry-renderer {
    border-radius: var(--glass-radius-sm) !important;
    transition: background 0.15s !important;
  }

  ytd-guide-entry-renderer:hover,
  ytd-mini-guide-entry-renderer:hover {
    background: var(--glass-bg-hover) !important;
    backdrop-filter: var(--glass-blur-light) !important;
    -webkit-backdrop-filter: var(--glass-blur-light) !important;
  }

  ytd-guide-entry-renderer[active],
  ytd-mini-guide-entry-renderer[active] {
    background: var(--glass-bg-active) !important;
    backdrop-filter: var(--glass-blur-light) !important;
    -webkit-backdrop-filter: var(--glass-blur-light) !important;
    border: 1px solid var(--glass-border) !important;
  }

  /* ─── VIDEO CARDS / THUMBNAILS ────────────────────────────── */
  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-compact-video-renderer,
  ytd-grid-video-renderer {
    background: var(--glass-bg) !important;
    backdrop-filter: var(--glass-blur-light) !important;
    -webkit-backdrop-filter: var(--glass-blur-light) !important;
    border: 1px solid var(--glass-border) !important;
    border-radius: var(--glass-radius-md) !important;
    box-shadow: var(--glass-shadow) !important;
    overflow: hidden !important;
    transition: transform 0.2s cubic-bezier(.34,1.56,.64,1), box-shadow 0.2s, border-color 0.2s !important;
  }

  ytd-rich-item-renderer:hover,
  ytd-video-renderer:hover,
  ytd-compact-video-renderer:hover,
  ytd-grid-video-renderer:hover {
    transform: translateY(-3px) scale(1.012) !important;
    box-shadow: var(--glass-shadow-hover) !important;
    border-color: var(--glass-border-strong) !important;
    background: var(--glass-bg-hover) !important;
  }

  /* Thumbnail rounded corners */
  ytd-thumbnail,
  ytd-thumbnail a,
  ytd-thumbnail img,
  #thumbnail {
    border-radius: var(--glass-radius-sm) !important;
    overflow: hidden !important;
  }

  /* ─── VIDEO METADATA BELOW THUMBNAIL ─────────────────────── */
  #meta,
  #details,
  ytd-video-meta-block {
    background: transparent !important;
    padding: 10px 14px 14px !important;
  }

  /* ─── CHIPS / FILTER PILLS ────────────────────────────────── */
  yt-chip-cloud-chip-renderer,
  ytd-feed-filter-chip-bar-renderer yt-chip-cloud-chip-renderer {
    background: var(--glass-bg) !important;
    backdrop-filter: var(--glass-blur-light) !important;
    -webkit-backdrop-filter: var(--glass-blur-light) !important;
    border: 1px solid var(--glass-border) !important;
    border-radius: var(--glass-radius-pill) !important;
    box-shadow: inset 0 1px 0 rgba(255,255,255,0.10) !important;
    transition: background 0.15s, border-color 0.15s !important;
  }

  yt-chip-cloud-chip-renderer:hover {
    background: var(--glass-bg-hover) !important;
    border-color: var(--glass-border-strong) !important;
  }

  yt-chip-cloud-chip-renderer[chip-style="STYLE_HOME_FILTER"][selected],
  yt-chip-cloud-chip-renderer[selected] {
    background: rgba(255,255,255,0.90) !important;
    color: #111 !important;
    border-color: transparent !important;
    backdrop-filter: none !important;
  }

  /* ─── BUTTONS (general) ────────────────────────────────────── */
  yt-button-shape button,
  ytd-button-renderer a,
  paper-button,
  .yt-spec-button-shape-next {
    border-radius: var(--glass-radius-pill) !important;
    transition: background 0.15s, box-shadow 0.15s !important;
  }

  /* Subscribe / primary CTA */
  ytd-subscribe-button-renderer button,
  yt-button-shape[subscribe] button {
    background: rgba(255,255,255,0.92) !important;
    color: #0a0a14 !important;
    border: none !important;
    border-radius: var(--glass-radius-pill) !important;
    box-shadow: 0 2px 12px rgba(0,0,0,0.15) !important;
  }

  /* Like / dislike / share action row */
  #top-level-buttons-computed segmented-like-dislike-button-view-model,
  ytd-toggle-button-renderer,
  .yt-spec-button-shape-next--tonal {
    background: var(--glass-bg) !important;
    backdrop-filter: var(--glass-blur-light) !important;
    -webkit-backdrop-filter: var(--glass-blur-light) !important;
    border: 1px solid var(--glass-border) !important;
    border-radius: var(--glass-radius-pill) !important;
  }

  /* ─── VIDEO PLAYER CHROME ─────────────────────────────────── */
  .ytp-chrome-bottom,
  .ytp-gradient-bottom {
    background: linear-gradient(
      to top,
      rgba(0,0,0,0.55) 0%,
      transparent 100%
    ) !important;
    backdrop-filter: blur(2px) !important;
    -webkit-backdrop-filter: blur(2px) !important;
    border-radius: 0 0 var(--glass-radius-md) var(--glass-radius-md) !important;
  }

  .ytp-progress-bar-container {
    border-radius: var(--glass-radius-pill) !important;
    overflow: visible !important;
  }

  .ytp-play-progress,
  .ytp-load-progress {
    border-radius: var(--glass-radius-pill) !important;
  }

  /* Player control buttons hover */
  .ytp-button:hover {
    background: var(--glass-bg-hover) !important;
    backdrop-filter: var(--glass-blur-light) !important;
    -webkit-backdrop-filter: var(--glass-blur-light) !important;
    border-radius: var(--glass-radius-sm) !important;
  }

  /* ─── COMMENTS SECTION ─────────────────────────────────────── */
  ytd-comment-renderer,
  ytd-comment-thread-renderer {
    background: var(--glass-bg) !important;
    backdrop-filter: var(--glass-blur-light) !important;
    -webkit-backdrop-filter: var(--glass-blur-light) !important;
    border: 1px solid var(--glass-border) !important;
    border-radius: var(--glass-radius-md) !important;
    box-shadow: var(--glass-shadow) !important;
    padding: 12px 16px !important;
    margin-bottom: 10px !important;
    transition: border-color 0.15s !important;
  }

  ytd-comment-renderer:hover,
  ytd-comment-thread-renderer:hover {
    border-color: var(--glass-border-strong) !important;
  }

  /* ─── SIDEBAR / UP NEXT ────────────────────────────────────── */
  ytd-compact-video-renderer {
    border-radius: var(--glass-radius-md) !important;
    padding: 8px !important;
    margin-bottom: 8px !important;
  }

  /* ─── DROPDOWN MENUS / POPUPS ─────────────────────────────── */
  tp-yt-paper-dialog,
  ytd-popup-container,
  ytd-menu-popup-renderer,
  yt-dropdown-menu,
  ytd-multi-page-menu-renderer {
    background: rgba(18, 18, 30, 0.72) !important;
    backdrop-filter: blur(32px) saturate(200%) !important;
    -webkit-backdrop-filter: blur(32px) saturate(200%) !important;
    border: 1px solid var(--glass-border) !important;
    border-radius: var(--glass-radius-lg) !important;
    box-shadow: var(--glass-shadow-hover), inset 0 1px 0 rgba(255,255,255,0.12) !important;
    overflow: hidden !important;
  }

  ytd-menu-service-item-renderer,
  tp-yt-paper-item {
    border-radius: var(--glass-radius-sm) !important;
    margin: 4px 8px !important;
    transition: background 0.12s !important;
  }

  ytd-menu-service-item-renderer:hover,
  tp-yt-paper-item:hover {
    background: var(--glass-bg-hover) !important;
  }

  /* ─── TOOLTIPS ─────────────────────────────────────────────── */
  tp-yt-paper-tooltip,
  .ytp-tooltip {
    background: rgba(18, 18, 30, 0.80) !important;
    backdrop-filter: var(--glass-blur-light) !important;
    -webkit-backdrop-filter: var(--glass-blur-light) !important;
    border: 1px solid var(--glass-border) !important;
    border-radius: var(--glass-radius-sm) !important;
    box-shadow: var(--glass-shadow) !important;
  }

  /* ─── NOTIFICATION PANEL ───────────────────────────────────── */
  ytd-notification-renderer {
    background: var(--glass-bg) !important;
    border-radius: var(--glass-radius-md) !important;
    border: 1px solid var(--glass-border) !important;
    margin: 6px 8px !important;
    transition: background 0.15s !important;
  }

  ytd-notification-renderer:hover {
    background: var(--glass-bg-hover) !important;
  }

  /* ─── CHANNEL PAGE HEADER ─────────────────────────────────── */
  ytd-channel-tagline-renderer,
  #channel-header-container {
    background: var(--glass-bg) !important;
    backdrop-filter: var(--glass-blur) !important;
    -webkit-backdrop-filter: var(--glass-blur) !important;
    border-radius: var(--glass-radius-lg) !important;
    border: 1px solid var(--glass-border) !important;
    box-shadow: var(--glass-shadow) !important;
  }

  /* ─── SHELF / SECTION CONTAINERS ─────────────────────────── */
  ytd-rich-section-renderer,
  ytd-shelf-renderer {
    background: var(--glass-bg) !important;
    backdrop-filter: var(--glass-blur-light) !important;
    -webkit-backdrop-filter: var(--glass-blur-light) !important;
    border: 1px solid var(--glass-border) !important;
    border-radius: var(--glass-radius-lg) !important;
    box-shadow: var(--glass-shadow) !important;
    padding: 16px !important;
    margin-bottom: 16px !important;
  }

  /* ─── SHORTS SHELF ─────────────────────────────────────────── */
  ytd-reel-shelf-renderer {
    background: var(--glass-bg) !important;
    border: 1px solid var(--glass-border) !important;
    border-radius: var(--glass-radius-lg) !important;
    backdrop-filter: var(--glass-blur-light) !important;
    -webkit-backdrop-filter: var(--glass-blur-light) !important;
    padding: 12px !important;
  }

  ytd-reel-item-renderer {
    border-radius: var(--glass-radius-md) !important;
    overflow: hidden !important;
    box-shadow: var(--glass-shadow) !important;
    transition: transform 0.2s cubic-bezier(.34,1.56,.64,1) !important;
  }

  ytd-reel-item-renderer:hover {
    transform: scale(1.04) !important;
  }

  /* ─── LIVE BADGE / PILLS ───────────────────────────────────── */
  .badge-style-type-live-now,
  ytd-badge-supported-renderer .badge {
    border-radius: var(--glass-radius-pill) !important;
    backdrop-filter: var(--glass-blur-light) !important;
    -webkit-backdrop-filter: var(--glass-blur-light) !important;
    box-shadow: 0 2px 8px rgba(0,0,0,0.25) !important;
  }

  /* ─── HIGHLIGHT — inset specular shimmer on glass surfaces ── */
  ytd-rich-item-renderer::before,
  ytd-video-renderer::before,
  ytd-comment-renderer::before {
    content: "" !important;
    position: absolute !important;
    inset: 0 !important;
    border-radius: inherit !important;
    background: linear-gradient(
      135deg,
      rgba(255,255,255,0.10) 0%,
      transparent 55%
    ) !important;
    pointer-events: none !important;
    z-index: 1 !important;
  }

  ytd-rich-item-renderer,
  ytd-video-renderer,
  ytd-comment-renderer {
    position: relative !important;
  }
}
